const OpeningScene = ({ onComplete }) => {
  const [currentText, setCurrentText] = useState(0)
  const [isVisible, setIsVisible] = useState(true)

  const storyTexts = [
    "Deep in the heart of Athens, Georgia...",
    "Where the red clay meets the rolling hills...",
    "There stands an old farm that has witnessed countless battles...",
    "Not battles of war, but battles of pride...",
    "Welcome to the legendary Chicken Pit...",
    "Where two teams of the finest fowl compete...",
    "For glory, for honor, for the ultimate prize...",
    "Who will emerge victorious from the pit?"
  ]

  useEffect(() => {
    const textTimer = setInterval(() => {
      setCurrentText(prev => {
        if (prev < storyTexts.length - 1) {
          return prev + 1
        } else {
          clearInterval(textTimer)
          // Start fade out after all text is shown
          setTimeout(() => {
            setIsVisible(false)
            setTimeout(() => {
              onComplete()
            }, 1000) // Wait for fade out to complete
          }, 1500) // Show last text for 1.5 seconds
          return prev
        }
      })
    }, 1000) // Change text every 1 second

    return () => clearInterval(textTimer)
  }, [onComplete, storyTexts.length])

  return (
    <div className={`opening-scene ${!isVisible ? 'fade-out' : ''}`}>
      <div className="opening-background">
        <div className="opening-overlay"></div>
        <div className="opening-content">
          <div className="opening-title">
            <h1>The Chicken Pit</h1>
            <div className="opening-subtitle">Athens, Georgia</div>
          </div>

          <div className="story-container">
            {storyTexts.map((text, index) => (
              <div
                key={index}
                className={`story-text ${index <= currentText ? 'visible' : ''} ${index === currentText ? 'current' : ''}`}
              >
                {text}
              </div>
            ))}
          </div>

          <div className="opening-footer">
            <div className="loading-dots">
              <span></span>
              <span></span>
              <span></span>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default OpeningScene"}

