.opening-background {
  width: 100%;
  height: 100%;
  background: 
    linear-gradient(to bottom, 
      rgba(135, 206, 235, 0.8) 0%,
      rgba(135, 206, 235, 0.6) 30%,
      rgba(255, 218, 185, 0.4) 60%,
      rgba(34, 139, 34, 0.6) 80%,
      rgba(139, 69, 19, 0.8) 100%
    ),
    linear-gradient(135deg, 
      #87CEEB 0%, 
      #98FB98 25%, 
      #F0E68C 50%, 
      #DEB887 75%, 
      #8B4513 100%
    );
  background-size: 400% 400%;
  animation: gradientShift 12s ease-in-out infinite;
  position: relative;
  overflow: hidden;
}

.opening-background::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: 
    /* Farm hills silhouette */
    radial-gradient(ellipse 800px 200px at 50% 90%, rgba(34, 139, 34, 0.6) 0%, transparent 50%),
    radial-gradient(ellipse 600px 150px at 20% 95%, rgba(107, 142, 35, 0.5) 0%, transparent 50%),
    radial-gradient(ellipse 700px 180px at 80% 92%, rgba(85, 107, 47, 0.5) 0%, transparent 50%),
    /* Barn silhouette */
    linear-gradient(to bottom, transparent 60%, rgba(139, 69, 19, 0.4) 65%, rgba(160, 82, 45, 0.3) 70%, transparent 75%),
    /* Fence posts */
    repeating-linear-gradient(90deg, 
      transparent 0px, 
      transparent 80px, 
      rgba(101, 67, 33, 0.3) 82px, 
      rgba(101, 67, 33, 0.3) 86px,
      transparent 88px,
      transparent 160px
    );
  background-position: 
    center bottom,
    left bottom,
    right bottom,
    center 70%,
    center 85%;
  animation: atmosphericGlow 8s ease-in-out infinite alternate;
}

.opening-background::after {
  content: '';
  position: absolute;
  top: 10%;
  left: 0;
  right: 0;
  bottom: 0;
  background: 
    /* Clouds */
    radial-gradient(ellipse 200px 60px at 20% 20%, rgba(255, 255, 255, 0.3) 0%, transparent 70%),
    radial-gradient(ellipse 150px 40px at 70% 15%, rgba(255, 255, 255, 0.25) 0%, transparent 70%),
    radial-gradient(ellipse 180px 50px at 85% 25%, rgba(255, 255, 255, 0.2) 0%, transparent 70%),
    /* Sun rays */
    conic-gradient(from 45deg at 85% 20%, 
      transparent 0deg, 
      rgba(255, 215, 0, 0.1) 30deg, 
      transparent 60deg,
      rgba(255, 215, 0, 0.08) 90deg,
      transparent 120deg,
      rgba(255, 215, 0, 0.1) 150deg,
      transparent 180deg
    );
  animation: cloudDrift 20s linear infinite, sunRays 15s ease-in-out infinite alternate;
  pointer-events: none;
}

.opening-title h1 {
  font-size: 4rem;
  font-weight: bold;
  color: #ffffff;
  text-shadow: 
    0 0 20px rgba(255, 215, 0, 0.8),
    0 0 40px rgba(255, 140, 0, 0.6),
    0 0 60px rgba(139, 69, 19, 0.4),
    3px 3px 10px rgba(0, 0, 0, 0.9),
    0 0 80px rgba(255, 69, 0, 0.3);
  margin: 0;
  font-family: 'Georgia', serif;
  letter-spacing: 2px;
  background: linear-gradient(45deg, #FFD700, #FF8C00, #CD853F);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  filter: drop-shadow(0 0 10px rgba(255, 215, 0, 0.5));
}

.opening-subtitle {
  font-size: 1.5rem;
  color: #F5DEB3;
  margin-top: 1rem;
  font-style: italic;
  text-shadow: 
    2px 2px 4px rgba(0, 0, 0, 0.8),
    0 0 10px rgba(245, 222, 179, 0.6);
  font-family: 'Georgia', serif;
  font-weight: 300;
}

@keyframes atmosphericGlow {
  0% { opacity: 0.4; }
  100% { opacity: 0.7; }
}

@keyframes cloudDrift {
